# Let's try a more systematic approach
# Start with a 13-cycle (vertices 0-12 in order)
# Then add chords that maintain girth >= 7

n = 13

# Base cycle
base_cycle = [(i, (i+1) % n) for i in range(n)]
print(f"Base cycle has {len(base_cycle)} edges")

# All possible chords (non-adjacent pairs)
all_chords = [(i, j) for i in range(n) for j in range(i+1, n) if (j - i) % n != 1 and (i - j) % n != 1 and (j - i) % n != n-1 and (i - j) % n != n-1]
print(f"Total possible chords: {len(all_chords)}")

# For a cycle of length 13, a chord between vertices at distance d creates cycles of length d+1 and 13-d+1
# For girth >= 7, we need d+1 >= 7 and 13-d+1 >= 7
# So d >= 6 and d <= 7 (since 13-d >= 6 means d <= 7)
# So d = 6 or d = 7

valid_chords = []
for (i, j) in all_chords:
    d = min((j - i) % n, (i - j) % n)
    if d >= 6 and d <= 7:
        valid_chords.append((i, j))

print(f"Valid chords (distance 6 or 7): {len(valid_chords)}")
print(f"Valid chords: {valid_chords}")

# Now we need to select a subset of these chords such that:
# 1. No cycles of length < 7 are created
# 2. The graph is 4-colorable
# 3. Total edges >= 22 (so we need at least 22 - 13 = 9 chords)

# Let's check: if we add multiple chords, we might create shorter cycles
# through combinations of chords

# Let's try to find a set of chords that works
import itertools

def has_short_cycle(edges, n, max_len=6):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        queue = [start]
        for u in queue:
            for v in adj[u]:
                if v == parent[u]:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= max_len:
                        return True
    return False

def is_4_colorable(edges, n):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(4):
            if c not in used:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

# Let's try all combinations of chords (there are 13 valid chords, so 2^13 = 8192 possibilities)
# That's manageable!

best_edges = 0
best_solution = None

for r in range(9, len(valid_chords) + 1):
    for combo in itertools.combinations(valid_chords, r):
        edges = base_cycle + list(combo)
        if not has_short_cycle(edges, n, 6):
            if is_4_colorable(edges, n):
                print(f"Found solution with {len(edges)} edges!")
                print(f"Edges: {edges}")
                best_edges = len(edges)
                best_solution = edges
                break
    if best_solution:
        break

if best_solution:
    print(f"\nSolution found: {best_solution}")
    print(f"Number of edges: {len(best_solution)}")
else:
    print("No solution found with this approach")
    # Let's try with fewer chords too
    for r in range(9, -1, -1):
        for combo in itertools.combinations(valid_chords, r):
            edges = base_cycle + list(combo)
            if not has_short_cycle(edges, n, 6):
                if is_4_colorable(edges, n):
                    print(f"Found solution with {len(edges)} edges!")
                    print(f"Edges: {edges}")
                    best_edges = len(edges)
                    best_solution = edges
                    break
        if best_solution:
            break
